// LogSanitize — build safe scalar values, no mustache-in-SQL
const e = ($input.first() || {}).json || {};
const ex = e.execution || {};
const wf = e.workflow || {};
const q = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const eidraw = Number.isInteger(ex.id) ? ex.id : parseInt(ex.id, 10);
const eid = Number.isFinite(eidraw) ? eidraw : 'NULL';
return [{ json: {
  eid: eid,
  wname: q(wf.name || 'unknown'),
  nname: q(ex.lastNodeExecuted || 'unknown'),
  emsg: q((ex.error && (ex.error.message || JSON.stringify(ex.error))) || e.error || 'unknown error').slice(0, 2000)
} }];
